    ("客戶", "NVDA", "輝達", "218.36", "-2.37%", "⚠️⚠️ 9/10 連 3 日下跌，收 $218.36（-2.37%，自 9/9 的 $223.67），三日自 $230.36 累計回檔 5.21%，並跌破 9/4 水準、創本波回檔新低。⭐ 相對強度的觀察本日首度反轉：輝達 -2.37% 小於費半的 -2.66%，⭐ 這是連續三個交易日落後費半之後首度優於費半。⚠️ 惟須誠實界定：在全族群下跌日「跌得比較少」是相對表現改善的最弱形式，不足以宣告動能回復。⚠️ 本報須標註：本次查證未取得 9/10 當日的個股別觸發新聞。"),
    ("客戶", "AAPL", "蘋果", "326.57", "+3.56%", "⭐⭐ 9/10 逆勢大漲 +3.56% 收 $326.57（自 9/9 的 $315.34），⭐ 為本報全部追蹤標的中 9/10 唯一的大漲，且發生在全族群重挫、標普 -0.58% 的一天。⭐ 它一舉收復 9/9 發表會當日的「賣新聞」跌幅（-0.28%）並突破 9/4 的 $319.97，創本波新高。⚠️⚠️ 本報必須誠實標註：本次查證未能取得 9/10 當日的明確個股觸發新聞（如預購數據、分析師升評），故不對漲因下定論，僅記錄價格事實。⭐ 對台積電的意義是間接但正向的：iPhone 18 Pro／Pro Max 搭載採台積電 2nm（N2）的 A20 Pro，蘋果股價在發表會後轉強，代表市場對該產品週期的信心回升，而該週期正是 N2 稼動率的主要支撐之一。"),
    ("客戶", "AVGO", "博通", "360.83", "-0.97%", "⚠️ 9/10 連 2 日下跌，收 $360.83（-0.97%，自 9/9 的 $364.38），跌破 9/4 的 $357.90 之上的整理區間下緣附近。⭐ 惟須記錄一項相對強度：-0.97% 的跌幅遠小於費半的 -2.66%，為本日客戶群中除蘋果外最抗跌者。⚠️ 判讀：本報 9/9 所記「市場對 AI 供應鏈僅小幅超標的容忍度已下降」的評價風險仍在，但本日並未惡化。"),
    ("客戶", "AMD", "超微", "503.60", "-3.36%", "⚠️ 9/10 收 $503.60（-3.36%，自 9/9 的 $521.10），終結連 2 日大漲，回吐 9/9 的 +3.04% 全部漲幅，惟仍站穩 $500 整數關卡之上、且高於 9/8 的 $505.74 略低一線。⭐ 判讀：本波自 9/4 的 $477.57 仍累計上漲 5.4%，回檔幅度小於漲幅，屬急漲後的正常換手。⭐ 對台積電的基本面判讀不變：MI350／MI450 全數由台積電代工並使用 CoWoS，「Q3 已出貨、Q4 放量」為已在進行中的投片，不因股價回檔而改變。"),
    ("客戶", "QCOM", "高通", "176.88", "+0.27%", "⭐ 9/10 逆勢小漲 +0.27% 收 $176.88（自 9/9 的 $176.40），連 3 日收紅並續創本波新高，⭐ 為本日除蘋果外唯一收紅的美股追蹤標的。⭐ 判讀：在費半 -2.66% 的一天仍能收紅，相對強度明確。"),
    ("客戶", "2454.TW", "聯發科", "4,720", "+2.05%", "⭐⭐ 9/10 逆勢反彈 +2.05% 收 4,720 元（-9/9 為 4,625 元），終結連 2 日下跌並收復 9/8 的 4,710 元，成交量自 4,731 張回升。⭐ 判讀：與日月光同日逆勢走強，台股 IC 設計與封測在台積電下跌日雙雙收紅；9/7 因輝達 35 億美元認購可轉債而漲停的行情，經 2 日整理後於本日重獲買盤。"),
    ("競爭", "INTC", "英特爾", "100.32", "-5.57%", "⚠️⚠️ 9/10 收 $100.32（-5.57%，自 9/9 的 $106.24），為本報全部追蹤標的中 9/10 第三大跌幅，⭐ 幾乎跌破 $100 整數關卡（僅高出 0.32 美元）。⚠️ 終結連 2 日收紅，回吐 9/8–9/9 兩日 +10.9% 漲幅中的過半。⭐ 判讀：9/8 的四項利多（Northland 升評、10 月 PC 處理器擬漲價約 10%、輝達持股揭露、Terafab 代工合作）在兩個交易日內即失去續航力，本報 9/9 所記「利多仍具續航力」的觀察在本日不再成立。⚠️ 對台積電的長期判讀維持不變：Intel 代工（IFS）若取得指標客戶則為長期競爭風險，惟 Terafab 案的量產時程與良率均未經證實。"),
    ("競爭", "005930.KS", "三星電子", "269,000 KRW", "-0.19%", "⚠️ 9/10 韓股小跌 -0.19% 收 269,000 韓元（自 9/9 的 269,500 韓元），終結連 2 日持平。⭐ 與同日 SK 海力士的 -0.16% 幅度相當，韓國半導體雙雄本日同步小幅回檔，9/9 的明顯分歧（海力士 +3.51%、三星持平）在本日消失。⚠️⚠️ 已標明時點的盤中補充：9/11 上午 09:55 KST 報 260,000 韓元（-3.35%），為盤中即時數據非收盤值——與海力士同步補跌。"),
    ("產業", "SOX", "費城半導體指數", "11,614.17", "-2.66%", "⚠️⚠️ 9/10 費半收 11,614.17（-2.66%、-317.15 點，自 9/9 的 11,931.32），⭐ 終結連 4 個交易日收紅，且為本報追蹤區間內的最大單日跌幅。⚠️ 跌幅遠大於同日大盤（標普 -0.58%、那斯達克 -0.65%），⭐ 這與 9/9「大盤跌而費半逆勢收紅」的型態完全相反——半導體在 9/9 展現的相對強度，於本日一日之內全數反轉。⚠️ 族群內部近乎全面下跌，重災區在設備與記憶體：科林研發 -5.65%、英特爾 -5.57%、美光 -4.90%、超微 -3.36%、應用材料 -3.17%、科磊 -3.13%、艾司摩爾 -2.43%、輝達 -2.37%；僅高通 +0.27% 收紅。⭐ 媒體歸因為總經因素合流（8 月 PPI 年增 5.4% 高於預期、布蘭特原油約 101 美元、10 年期公債殖利率 4.94%）而非半導體的產業面利空。⭐ 對台積電的意義：ADR -1.68% 弱於大盤但明顯抗跌於費半（差 0.98 個百分點），⭐ 且同日公布的 8 月營收創新高恰好證明需求端無虞——本報據此判定 9/10 的下跌屬評價（分母）壓縮而非獲利（分子）惡化。⚠️ 惟須並陳：費半自 9/4 的 11,735.26 已跌破，本波反彈的起漲區間正在被侵蝕。"),
