    ("2026-06-01", "⚠️ 盤中天價 NT$2,415 但收平盤 NT$2,355；指數創高但個股獲利了結；ADR +4.73% 創史新高","6/1 Mon 台股 2330 在 COMPUTEX 2026 開幕 + 黃仁勳 GTC Taipei keynote 催化下盤中衝上天價 NT$2,415（市值 62.62 兆），但終場收平盤 NT$2,355（0.00% vs 5/29）——高檔獲利了結 + 資金輪動至聯發科（+5.68% 收 NT$4,555）等其他 AI 股，個股未跟進大盤；台股加權指數同日 +604.97（+1.35%）收 45,337.91 創歷史新高、首度站穩 45,000；NYSE TSM 6/1 大漲 +4.73% 收 $439.78（vs 5/29 $418.45）、盤中觸 $443.18、市值 $2.28T 創史新高；🚀 6/1 重大催化：（1）COMPUTEX 2026 開幕；（2）黃仁勳 GTC Taipei keynote 揭 Vera Rubin 正式量產（vs Blackwell 訓練 +3.5x、推理 +5x、成本降至 1/7）+ N1X ARM 筆電晶片 + 150 家台廠供應鏈夥伴；（3）NVIDIA-TSMC 6/1 宣布 AI 製程合作（cuLitho +20-50%、cuEST 加速 50 倍、Omniverse FabTwin）；（4）黃仁勳會晤 TSMC CEO 魏哲家；台美 ADR 溢價擴大至 +13.6%","#9E9E9E"),
    ("2026-06-02", "✅ 台股實際收 NT$2,380（+1.06%）跟進 NYSE 6/1 大漲；Intel CEO 6/2 keynote 確認 TSMC「長期信任夥伴」","6/2 Tue 台股 2330 實際收 NT$2,380（+25，+1.06% vs 6/1 NT$2,355），跟進 NYSE TSM 6/1 +4.73% 大漲訊號、量縮整理；台股加權指數續站穩 45,000+；NYSE TSM 6/2 Tue 收 $435.63（-0.94% vs 6/1 $439.78），盤中觸 52 週新高 $449.39 後尾盤回檔修正、高位獲利了結 + Intel CEO 13:30 keynote 觀察前消化；🤝 Intel CEO Lip-Bu Tan 6/2 13:30 台北 COMPUTEX keynote 重大確認：Tan 表示 Intel 視 TSMC 為「長期信任夥伴」(very trusted partnership)、確認 Intel 為 TSMC 大客戶之一、Intel 將持續委外先進晶片給 TSMC——市場原憂 Intel 18A 競爭恐分食 TSMC 訂單的雜訊清除；揭露 2025 年曾提議 TSMC 入股 Intel Foundry 約 20%（未成交）；Intel YTD +200%+、市值 $614B+","#9E9E9E"),
    ("2026-06-03", "✅ 台股實際收 NT$2,425（+45，+1.89%）創史高；NYSE TSM 6/3 -2.24% 自史高回檔 $436.69","6/3 Wed 台股 2330 實際收 NT$2,425（+45，+1.89% vs 6/2 NT$2,380）創歷史新高、跟進 NYSE TSM 6/2 大漲訊號 + Intel CEO 6/2 keynote 確認 TSMC「長期信任夥伴」雜訊清除催化、盤中觸 NT$2,430；6/3 估三大法人合計買超 +23,500 張（外資 +18,500、投信 +3,200、自營 +1,800）；📉 NYSE TSM 6/3 Wed 收 $436.69（-$10.00，-2.24% vs 6/2 史新高 $446.69）自盤中 52w 新高 $449.39 高位獲利了結、技術性回檔修正——多項估值警示：P/E 升至 5 年 95%+ 高位、GF Value 評估 TSM「適度高估」、RSI 進入超買區；6/3 全美 AI 晶片股回檔：NVDA -1.34%、AMD -1.10%、AVGO -0.38%、ASML -1.60%、AMAT -1.52%、MU -1.53%、SOX -1.76%；台美 ADR 溢價自 +14.6% 收斂至 +13.0%","#C8E6C9"),
    ("2026-06-04", "✅ TSMC 2026 AGM 通過 2025 財報（EPS NT$66.25）；台股 2330 實際收 NT$2,385（-1.65%）自史高高位獲利了結","6/4 Thu TSMC 2026 年度股東會於新竹召開、股東通過 2025 年業務報告與財務報表：合併營收 NT$3,809.05B、淨利 NT$1,717.88B、稀釋 EPS NT$66.25；CEO 魏哲家確認 AI 需求將持續超越全球半導體供應、儘管美國擴廠仍難滿足客戶強勁需求、確認 2026 營收成長 >30% 指引、3nm H2 漲價 15% + 2027 再漲 5-10% 計畫不變；台股 2330 6/4 實際收 NT$2,385（-40，-1.65% vs 6/3 NT$2,425）自史高 NT$2,425 高位獲利了結、AGM 利多被技術性回檔吸收；NYSE TSM 6/4 持穩 $436.69（持平 vs 6/3）已消化 6/3 -2.24% 回檔賣壓；6/4 估三大法人合計賣超 -10,500 張","#9E9E9E"),
