    ("2026-06-16", "🚀 台股 2330 放量上攻收 NT$2,375（+2.81%）跟進 ADR 飆漲；SK 海力士-TSMC HBM4 合作","6/16 Tue 台股 2330 跟進 NYSE TSM 6/15 +4.12% 飆漲訊號放量上攻、收 NT$2,375（+65、+2.81% vs 6/12 NT$2,310）、市值回升 NT$61.6 兆；🤝 重大合作：SK 集團會長崔泰源 6/3 會晤 TSMC 董事長魏哲家、雙方就 HBM4 基底晶粒、先進邏輯製程、客製化 AI 記憶體展開合作；💰 TSMC CFO 重申先進製程漲價勢在必行（通膨+AI 需求）、3nm H2 漲 ~15%、sub-5nm 漲 5-10%；🏆 NVIDIA 確認 TSMC 第 1 大客戶、發表 Vera CPU + RTX Spark 超晶片由 TSMC 代工；技術面 RSI 64、KDJ J(92) 進入高檔留意過熱；上方壓力 NT$2,400 / NT$2,425 / NT$2,440 史高、下方支撐 NT$2,310 / NT$2,250；⚠️ 競爭雜訊：Google 向 Intel Foundry 下單逾 300 萬顆自研 TPU、Samsung 推進 HPB 封裝","#C8E6C9"),
    ("2026-06-17", "📉 NYSE TSM 6/16 -3.53% 自高回檔 $425.83；台股 2330 6/17 跟進估收 NT$2,315（-2.53%）；TSMC-Amkor 簽 10 年美國封裝長約","6/17 Wed NYSE TSM 6/16 Tue 收 $425.83（-$15.57、-3.53% vs 6/15 $441.40、成交量 1,109 萬股、P/E 33.07、市值 $1.97 兆）、逼近 52 週/史高 $450.16 後高位獲利了結、技術性回檔；台股 2330 6/17 跟進 ADR 回檔估收 NT$2,315（-60、-2.53% vs 6/16 NT$2,375）、市值回落 NT$60.0 兆（官方收盤以 TWSE 為準）；🤝 重大合作：TSMC-Amkor 宣布 10 年美國先進封裝長約、Amkor 將就近承接 TSMC Arizona 廠晶圓的封裝測試、強化美國半導體供應鏈在地化、呼應 TSMC $165B 美國投資承諾；📦 CoWoS 封裝瓶頸續為產業關鍵、TSMC 規劃自 2024 底 ~35K wpm 擴至 2026 底 ~130K wpm、5.5 倍光罩封裝良率 >98%；6/17 估三大法人合計賣超（外資估 -9,500 張）；技術面 RSI 自 64 回落至 55、KDJ J 自 92 急回至 50 高檔死叉浮現、MACD 紅柱縮短；下方支撐 NT$2,300 / NT$2,250、上方壓力 NT$2,375（6/16 收）/ NT$2,400 / NT$2,440 史高","#FFF9C4"),
    ("2026-06-18", "📈 台美雙市反彈、SpaceX IPO 將 TSMC 擠至全球市值第 7；台股 2330 6/18 估收 NT$2,385（+0.42%）", "6/18 Thu NYSE TSM 6/17 Wed 收 $432.15（+$6.32、+1.48% vs 6/16 $425.83、成交量 1,096 萬股、P/E 32.79、市值 $1.96 兆）自 6/16 -3.53% 回檔後低接買盤回補、盤中觸 $439.60；台股 2330 6/18 跟進 ADR 反彈估收 NT$2,385（+10、+0.42% vs 6/17 NT$2,375）、市值回升 NT$61.9 兆；🛰️ SpaceX 創紀錄 IPO（估值 $2.519 兆、募資 ~$750 億、+19.6%）市值超越 TSMC（$2.289 兆）、將台積電擠至全球市值第 7（屬外部排名變動、基本面未受影響）；🤝 TSMC-Amkor 簽 10 年美國先進封裝長約（6/16 公告、Peoria AZ $70 億、2028 投產、~2,000 就業、InFO/CoWoS）；🏆 NVIDIA Vera Rubin NVL72 採 TSMC N3+CoWoS-L、首搭 8 層 HBM4；6/18 估三大法人合計買超（外資估 +6,000 張）；⚠️ 6/19 Fri 端午節 TWSE 休市、6/18 為連假前最後交易日；技術面 RSI 自 55 回升至 58、KDJ J 自 50 回升至 70 低檔金叉浮現、MACD 紅柱止縮微張；下方支撐 NT$2,360 / NT$2,310、上方壓力 NT$2,400 / NT$2,425 / NT$2,440 史高", "#C8E6C9"),
    ("2026-06-19", "🎌 端午節 TWSE 休市", "6/19 Fri 端午節台股休市；NYSE TSM 照常交易、連假期間美股變數待觀察",                                        "#9E9E9E"),
    ("2026-06-22", "🚀 台美雙市再創歷史新高", "6/22 Mon 台股 2330 官方收 NT$2,510（+100、+4.15% vs 6/18 NT$2,410、量 39,134 張、市值 NT$65.1 兆）創歷史新高、受 6/18 NYSE +6.94% 飆漲帶動跳空大漲；NYSE TSM 6/22 收 $467.67（+$5.55、+1.20%）再創收盤紀錄新高、市值約 $2.4 兆；本波飆漲主因：TSMC-Amkor 10 年美國先進封裝長約（6/16 公告）+ 分析師升評 + AI 需求；ADR 溢價收斂至 +15.71%",      "#9E9E9E"),
    ("2026-06-23", "⚠️ 半導體全面拋售、ADR 暴跌 -6.69% 但台股相對抗跌", "6/23 Tue 台股 2330 官方收 NT$2,490（-20、-0.80% vs 6/22 NT$2,510、量 34,148 張、市值 NT$64.6 兆）相對抗跌、盤中觸歷史新高 NT$2,535 後拉回收最低；⚠️ NYSE TSM 6/23 暴跌 -6.69% 收 $436.39（-$31.28 vs 6/22 $467.67、市值回落約 $1.97 兆、P/E ~31.3）——半導體類股全面拋售：Micron -11.4%、AMD -6.25%、AVGO -5.02%、設備股跌 4.5-5%；崩跌觸發：Broadcom 指引不如預期引爆 sell-the-news + BoFA 升息報告推升美債殖利率 + 亞股下挫 + AI 過熱疑慮 + 財報前獲利了結，單日逾千億美元半導體市值蒸發；⚠️ TSMC 4-5 月營收 +24% YoY 落後華爾街 ~35% 預期、近期營收恐 miss、6 月營收（7 月上旬）為關鍵；📈 逆勢利多：Susquehanna 將 TSM 目標價自 $500 上調至 $575；台美 ADR 溢價自 +15.71% 大幅收斂至 +8.83%；6/23 估三大法人轉賣超（外資估 -9,000 張）",      "#FFCDD2"),
    ("2026-06-24", "⭐ 漲價題材引爆 ADR 隔夜大漲", "6/24 Wed TSMC 通知客戶漲價範圍擴大至 7nm 以下全製程（佔晶圓營收 ~75%）、幅度 5-10%；NYSE TSM 隔夜先跌後因漲價消息盤後跳漲；台股 2330 6/24 官方收 NT$2,390（跟進 6/23 ADR 暴跌補跌後止穩）",  "#C8E6C9"),
    ("2026-06-25", "📊 ADR 收 $440.83 +1.02%、台股平盤", "6/25 Thu NYSE TSM 收 $440.83（+1.02%、+$4.44）、盤後一度 +2.48% 至 $451.76；台股 2330 6/25 官方收 NT$2,390 平盤（0.00%、量 34,271 張、成交值 NT$822.97 億、尾盤賣壓自 2,410 殺回 2,390）",  "#9E9E9E"),
    ("2026-06-26", "📉 雙市回吐隔夜漲價漲幅", "6/26 Fri 台股 2330 官方收 NT$2,340（-50、-2.09% vs 6/25 NT$2,390、量放大至 53,800 張、外資賣超 6,104 張）；NYSE TSM 6/26 收 $432.35（-$2.64、-0.61% vs 6/25 $434.99、日內 $419.19–$436.13、市值約 $2.0 兆、P/E ~31.0）——連續回吐 6/24 漲價題材帶動之隔夜漲幅、估值與營收疑慮拉鋸；24/7 Wall St 探討 TSM 年底前能否站上 $500",  "#FFCDD2"),
    ("2026-06-29", "🚀 台股反彈、NYSE TSM 大漲 +5.26% 創波段新高", "6/29 Mon 台股 2330 官方收 NT$2,370（+30、+1.28% vs 6/26 NT$2,340、量縮 38,133 張、成交額 903.37 億、開 2,330/高 2,395）自 6/26 反彈；🚀 NYSE TSM 6/29 大漲 +5.26%（+$22.75）收 $455.10 創波段新高、市值約 $2.1 兆——⭐ TSMC-Winbond 特殊 DRAM（WoW 3D 堆疊）合作降低 HBM 對 Samsung/SK 依賴 + 漲價定價力 + BofA 上調目標三催化",  "#9E9E9E"),
