    ("2026-07-14", "📉 法說會前觀望：大盤重挫 642 點、2330 相對抗跌、外資賣超擴大", "7/14 Tue 台股 2330 官方收 NT$2,420（-20、-0.82% vs 7/13 NT$2,440、開 2,410／高 2,430／低 2,390、量 42,857 張 TWSE 口徑、額 NT$1,033.71 億）——加權指數重挫 -642.57 點（-1.42%）收 44,737.95、2330 相對抗跌惟失守 5MA；三大法人合計賣超 8,005 張：外資 -12,416（連 4 賣、4 日 -31,365）、投信 +1,841、自營 +2,570；NYSE TSM 7/14 收 $420.39（-0.28%）連 3 日小跌、⚡ 同日 SOX +2.54% 大反彈（NVDA +4.06%、MU +4.92%）TSM 落後屬法說會前觀望",  "#FFCDD2"),
